export const lessons = [
 {id:'inputs',title:'Choose input types',time:'6 min',intro:'The meaning of a value decides its type. The mathematical operation does not decide how the input line starts.',points:['input() returns text, even when someone types digits.','Use int(input(...)) for a whole count. Use float(input(...)) for a price or measurement that may have decimals.','Use input() for names and codes such as 007. Use direct assignment when a value is fixed in the task.'],code:'name = input("Name: ")\npages = int(input("Pages: "))\nminutes = float(input("Minutes: "))\nroom_code = input("Room code: ")\nbonus = 2',checks:[{id:'input-a',prompt:'What does this print?',code:'print("7" + "3")',answers:['73'],why:'Both values are strings, so + joins them. It does not add numbers.',hint:'Quotation marks make these values text.'},{id:'input-b',prompt:'Write the type that accepts a measurement such as 2.75: int, float or str.',code:'time = _____(input("Time: "))',answers:['float'],why:'float accepts decimal numeric text. int(input()) expects integer text such as 2.',hint:'A measurement can include a fractional part.'}]},
 {id:'operations',title:'Write calculations',time:'7 min',intro:'Python uses symbols such as * and /. Parentheses show which values belong together.',points:['Multiply with *. Divide with /. Division gives a float, including 8 / 2 → 4.0.','For nonnegative whole counts, // gives complete groups and % gives the remainder. % is not a percentage command.','Calculate a percentage with part / whole * 100. Check that the denominator is greater than zero. ** means power.'],code:'total = price * quantity\naverage = (a + b + c) / 3\npercentage = correct / questions * 100\ndiscount = price * 15 / 100\nsquare_area = side ** 2',checks:[{id:'op-a',prompt:'Predict the printed output.',code:'print((6 + 3) / 3)',answers:['3.0','3'],why:'Parentheses give 9 first. Python division then gives 3.0.',hint:'Add the values inside the parentheses before dividing.'},{id:'op-b',prompt:'Predict the printed output.',code:'print(17 % 5)',answers:['2'],why:'Three complete groups of 5 use 15. The remainder is 2.',hint:'How many items are left after making complete groups of five?'}]},
 {id:'decisions',title:'Read decisions',time:'6 min',intro:'Assignment stores a value. Comparison asks a question. A boundary test proves what happens exactly at a threshold.',points:['Use = for assignment and == for comparison.','Every if, elif and else line ends with a colon. Indent the statements inside each branch.','Use one if/elif/else chain when exactly one classification should print. Test below, equal and above.'],code:'if score < target:\n    print("Below target")\nelif score == target:\n    print("On target")\nelse:\n    print("Above target")',checks:[{id:'if-a',prompt:'Predict the printed output.',code:'score = 12\ntarget = 12\nif score < target:\n    print("Below")\nelif score == target:\n    print("Equal")\nelse:\n    print("Above")',answers:['Equal'],why:'12 is equal to 12, so the elif branch runs.',hint:'Equality must be checked separately from <.'},{id:'if-b',prompt:'Write the two-character operator that means “is equal to”.',code:'if total ____ target:',answers:['=='],why:'== compares two values. A single = assigns a value.',hint:'Use two equals signs for a comparison.'}]},
 {id:'debug',title:'Debug one cause',time:'7 min',intro:'Read the evidence, isolate a cause, make a small repair and retest. The next error may only appear after the first repair.',points:['A syntax error prevents execution. A runtime error occurs while the program runs. A logic error can produce the wrong answer without crashing.','In a debugging log, record the symptom, isolated cause, original line, correction and retest result.','Explain why the repair solves the problem. “It works” is weaker than a specific input and output.'],code:'price = "3.5"\n# Fix the cause before multiplying.\nprice = float(price)\nprint("Cost:", price * 2)',checks:[{id:'debug-a',prompt:'Which error type is caused by the missing colon? Answer syntax, runtime or logic.',code:'if total > 5\n    print(total)',answers:['syntax','syntax error','SyntaxError'],why:'Python cannot parse this if statement without its colon.',hint:'Can the program begin execution with this line?'},{id:'debug-b',prompt:'Predict the printed output.',code:'print("Cost:", 2.5 * 4)',answers:['Cost: 10.0','Cost: 10'],why:'The comma passes the label and the number separately to print().',hint:'Multiplication happens before print displays its arguments.'}]},
 {id:'testing',title:'Test boundaries',time:'6 min',intro:'Choose inputs deliberately. Predict the result before running, then compare it with what actually happened.',points:['Use contrasting tests: below, equal and above a threshold.','Use a relevant edge case, such as zero minutes, zero items or all-zero scores. Specify what the program should do.','For a loop, trace how a total changes. Initialize a running total once before the loop and add each new value.'],code:'total = 0\nfor turn in range(3):\n    points = float(input("Points: "))\n    total += points\nprint("Total:", total)',checks:[{id:'test-a',prompt:'For target = 15, which whole-number score checks equality?',code:'if score == target:',answers:['15'],why:'An equality boundary test must use the threshold itself.',hint:'The boundary is the exact target.'},{id:'test-b',prompt:'Predict the final printed output.',code:'total = 0\nfor value in [2, 4, 1]:\n    total += value\nprint(total)',answers:['7'],why:'The running totals are 2, 6 and 7. Resetting total inside the loop would erase earlier additions.',hint:'Keep the earlier total and add the next value.'}]},
 {id:'improve',title:'Improve and explain',time:'5 min',intro:'A repair restores required behavior. An improvement adds useful new behavior after the core program works.',points:['Choose a feature with a clear purpose: explain a result, validate an input or show a useful extra value.','Write a new test for your feature. Rerun the original tests to check that the required behavior still works.','Explain how input types, calculations, conditions and output work together. Refer to your own variable names and test evidence.'],code:'if points > target:\n    print("Extra points:", points - target)',checks:[{id:'improve-a',prompt:'After adding a feature, should you rerun the original tests? Answer yes or no.',code:'# A new feature can affect earlier behavior.',answers:['yes'],why:'Regression testing checks that the original required behavior remains correct.',hint:'A new feature might change a variable or condition used elsewhere.'},{id:'improve-b',prompt:'Predict the extra printed output.',code:'points = 18\ntarget = 14\nif points > target:\n    print("Extra points:", points - target)',answers:['Extra points: 4'],why:'18 minus 14 is 4. The condition is true, so the extra line prints.',hint:'Subtract the target from the points.'}]}
];

export const challenges=[
 {id:'pace',title:'Reading pace checker',level:'Start here',task:'Read a whole page count, decimal minutes and a target pace. When minutes is greater than zero, divide pages by minutes and print Below target, On target or Above target, followed by Pace: and the value. Otherwise print Enter minutes above zero. Repair four faults.',starter:'pages = input("Pages: ")\nminutes = float(input("Minutes: "))\ntarget = float(input("Target pace: "))\nif minutes > 0:\n    pace = pages * minutes\n    if pace = target:\n        print("On target")\n    elif pace < target:\n        print("Below target")\n    else:\n        print("Above target")\n    print("Pace: " + pace)\nelse:\n    print("Enter minutes above zero.")',solution:'pages = int(input("Pages: "))\nminutes = float(input("Minutes: "))\ntarget = float(input("Target pace: "))\nif minutes > 0:\n    pace = pages / minutes\n    if pace == target:\n        print("On target")\n    elif pace < target:\n        print("Below target")\n    else:\n        print("Above target")\n    print("Pace:", pace)\nelse:\n    print("Enter minutes above zero.")',hints:['First find the comparison that Python cannot parse.','pages is numeric input. Decide whether it is a count or a decimal measurement.','A pace in pages per minute divides pages by minutes. Keep the zero guard before that division.','Print the number as a separate argument rather than joining a float directly to text.'],tests:[{label:'Below target',inputs:['12','3','5'],expected:'Below target\nPace: 4.0'},{label:'Equal to target',inputs:['15','3','5'],expected:'On target\nPace: 5.0'},{label:'Above target',inputs:['18','3','5'],expected:'Above target\nPace: 6.0'},{label:'Zero minutes',inputs:['12','0','5'],expected:'Enter minutes above zero.'}]},
 {id:'average',title:'Quiz average checker',level:'Practise calculations',task:'Read three decimal scores. Calculate their mean and compare it with the fixed target 6. Print Below target, On target or Above target, then Average: and its value. Repair four faults. Use nonnegative scores.',starter:'first = input("First score: ")\nsecond = float(input("Second score: "))\nthird = float(input("Third score: "))\naverage = first + second + third / 3\nif average = 6:\n    print("On target")\nelif average < 6:\n    print("Below target")\nelse:\n    print("Above target")\nprint("Average: " + average)',solution:'first = float(input("First score: "))\nsecond = float(input("Second score: "))\nthird = float(input("Third score: "))\naverage = (first + second + third) / 3\nif average == 6:\n    print("On target")\nelif average < 6:\n    print("Below target")\nelse:\n    print("Above target")\nprint("Average:", average)',hints:['Repair the comparison syntax so the program can start.','All three inputs must be numbers before adding them.','The whole sum must be divided by 3. Use parentheses.','Check how the final print handles a text label and a number.'],tests:[{label:'Below target',inputs:['3','4','5'],expected:'Below target\nAverage: 4.0'},{label:'Equal to target',inputs:['5','6','7'],expected:'On target\nAverage: 6.0'},{label:'Above target',inputs:['7','8','9'],expected:'Above target\nAverage: 8.0'},{label:'All zero',inputs:['0','0','0'],expected:'Below target\nAverage: 0.0'}]},
 {id:'total',title:'Club points collector',level:'Loop extension',task:'Read three decimal scores, accumulate their total and compare it with 10. Print Keep practising, Target reached or Target exceeded, then Total: and its value. Repair four faults. Keep the loop and use nonnegative scores.',starter:'total = 0\nfor turn in range(3)\n    score = input("Points: ")\n    total = score\nif total < 10:\n    print("Keep practising")\nelif total == 10:\n    print("Target reached")\nelse:\n    print("Target exceeded")\nprint("Total: " + total)',solution:'total = 0\nfor turn in range(3):\n    score = float(input("Points: "))\n    total += score\nif total < 10:\n    print("Keep practising")\nelif total == 10:\n    print("Target reached")\nelse:\n    print("Target exceeded")\nprint("Total:", total)',hints:['Check the end of the for line.','Convert the input so score is a number.','The total should keep the earlier scores and add each new one.','The final print must display a label together with a numeric total.'],tests:[{label:'Below target',inputs:['1','2','3'],expected:'Keep practising\nTotal: 6.0'},{label:'Equal to target',inputs:['2.5','3','4.5'],expected:'Target reached\nTotal: 10.0'},{label:'Above target',inputs:['4','4','4'],expected:'Target exceeded\nTotal: 12.0'},{label:'All zero',inputs:['0','0','0'],expected:'Keep practising\nTotal: 0.0'}]}
];

export function answerMatches(value,answers){const norm=s=>String(s).trim().replace(/^['"]|['"]$/g,'').replace(/\s+/g,' ').toLowerCase();return answers.some(a=>norm(a)===norm(value));}
export function outputMatches(actual,expected){const normalize=s=>s.trim().split('\n').map(l=>l.trimEnd());const a=normalize(actual),b=normalize(expected);return b.every((line,i)=>a[i]===line);}
